package com.ejemplo.alquileres.controller;
import com.ejemplo.alquileres.model.*; import com.ejemplo.alquileres.service.PropietarioService; import com.ejemplo.alquileres.ui.*;
import javafx.beans.property.SimpleStringProperty; import javafx.collections.*; import javafx.fxml.FXML; import javafx.scene.control.*; import javafx.scene.layout.VBox; import org.springframework.data.domain.Page; import org.springframework.stereotype.Component;
@Component public class PropietarioController implements Refrescable {
 private final PropietarioService service;private final Tareas tareas;private final Notificador aviso;private final ObservableList<Propietario> datos=FXCollections.observableArrayList();private Long id;private boolean activo=true;
 @FXML private TextField buscar,documento,nombre,telefono,email,banco,cuenta;@FXML private ComboBox<TipoDocumento> tipo;@FXML private CheckBox activos;@FXML private TableView<Propietario> tabla;@FXML private TableColumn<Propietario,String> colNombre,colDocumento,colTelefono,colEmail,colEstado;@FXML private VBox drawer;@FXML private Label titulo;
 public PropietarioController(PropietarioService s,Tareas t,Notificador a){service=s;tareas=t;aviso=a;}@FXML public void initialize(){tipo.setItems(FXCollections.observableArrayList(TipoDocumento.values()));tipo.setValue(TipoDocumento.DNI);activos.setSelected(true);colNombre.setCellValueFactory(c->new SimpleStringProperty(c.getValue().getNombre()));colDocumento.setCellValueFactory(c->new SimpleStringProperty(c.getValue().getTipoDocumento()+" "+c.getValue().getNumeroDocumento()));colTelefono.setCellValueFactory(c->new SimpleStringProperty(c.getValue().getTelefono()));colEmail.setCellValueFactory(c->new SimpleStringProperty(c.getValue().getEmail()));colEstado.setCellValueFactory(c->new SimpleStringProperty(c.getValue().isActivo()?"Activo":"Inactivo"));tabla.setItems(datos);buscar.textProperty().addListener((o,a,b)->refrescar());activos.selectedProperty().addListener((o,a,b)->refrescar());tabla.setOnMouseClicked(e->{if(e.getClickCount()==2)editar(tabla.getSelectionModel().getSelectedItem());});}public void refrescar(){tareas.ejecutar(()->service.listar(buscar.getText(),activos.isSelected()?true:null,0,100),this::mostrar,e->aviso.error(msg(e)));}private void mostrar(Page<Propietario>p){datos.setAll(p.getContent());}
 @FXML private void onNuevo(){id=null;activo=true;documento.clear();nombre.clear();telefono.clear();email.clear();banco.clear();cuenta.clear();tipo.setValue(TipoDocumento.DNI);titulo.setText("Nuevo propietario");abrir();}@FXML private void onEditar(){editar(tabla.getSelectionModel().getSelectedItem());}private void editar(Propietario p){if(p==null)return;id=p.getId();activo=p.isActivo();tipo.setValue(p.getTipoDocumento());documento.setText(p.getNumeroDocumento());nombre.setText(p.getNombre());telefono.setText(n(p.getTelefono()));email.setText(n(p.getEmail()));banco.setText(n(p.getBanco()));cuenta.setText(n(p.getCuenta()));titulo.setText("Editar propietario");abrir();}@FXML private void onGuardar(){Propietario p=Propietario.builder().id(id).tipoDocumento(tipo.getValue()).numeroDocumento(documento.getText()).nombre(nombre.getText()).telefono(telefono.getText()).email(email.getText()).banco(banco.getText()).cuenta(cuenta.getText()).activo(activo).build();tareas.ejecutar(()->service.guardar(p),x->{cerrar();aviso.info("Propietario guardado.");refrescar();},e->aviso.error(msg(e)));}@FXML private void onEliminar(){Propietario p=tabla.getSelectionModel().getSelectedItem();if(p==null)return;tareas.ejecutar(()->{service.eliminar(p.getId());return null;},x->{aviso.info("Propietario eliminado o desactivado según sus referencias.");refrescar();},e->aviso.error(msg(e)));}@FXML private void onCerrar(){cerrar();}private void abrir(){drawer.setVisible(true);drawer.setManaged(true);}private void cerrar(){drawer.setVisible(false);drawer.setManaged(false);}private String n(String v){return v==null?"":v;}private String msg(Throwable e){return e.getCause()!=null?e.getCause().getMessage():e.getMessage();}
}
